head.script:
scwin.checktype1 = function() {
	return typeof g1_0_w2_g1_0_w2_gg1_0_group1 === 'undefined';
};

scwin.checktype2 = function() {
	return typeof g1_0_w2_g1_0_w2_gg1_1_group1 === 'undefined';
};

scwin.checktype3 = function() {
	return typeof g1_1_w2_g1_1_w2_gg1_0_group1 === 'undefined';
};

scwin.checktype4 = function() {
	return typeof g1_1_w2_g1_1_w2_gg1_1_group1 === 'undefined';
};

scwin.checktype5 = function() {
	return typeof g1_2_w2_g1_2_w2_gg1_0_group1 === 'undefined';
};

scwin.checktype6 = function() {
	return typeof g1_2_w2_g1_2_w2_gg1_1_group1 === 'undefined';
};

scwin.checktype7 = function() {
	return typeof g1_3_w2_g1_3_w2_gg1_0_group1 === 'undefined';
};

// generator > wframe(scope) > generator 로 만든 group id - 정상 형식 개수|접두사 중복 id 개수. 2026-11
scwin.checkGroups = function() {
	var ids = Array.prototype.map.call(document.querySelectorAll('[id$=_group1]'), function(e) { return e.id; });
	var ok = ids.filter(function(id) { return /^(mf_)?w1_g1_\d_w2_gg1_\d_group1$/.test(id); }).length;
	var dup = ids.filter(function(id) { return /(g1_\d_w2_){2}/.test(id); }).length;
	return ok + '|' + dup;
};
scwin.checktype8 = function() {
	return typeof g1_3_w2_g1_3_w2_gg1_1_group1 === 'undefined';
};
